// פגישת וידאו באפליקציה (26.10.26): למתאמן/ת עם תגית "אונליין" ופגישה היום או מחר — כפתור הצטרפות עם הקישור הקבוע של אביאל
function videoFor_(name) { try { if ((onbState(name).tags || []).indexOf('אונליין') < 0) return ''; const link = PropertiesService.getScriptProperties().getProperty('video_link') || ''; if (!link) return '';
  const nm = clientRow(name).get('פגישה הבאה'); if (!(nm instanceof Date)) return ''; const dd = Math.round((startOfDay(nm) - startOfDay(new Date())) / 864e5); return dd >= 0 && dd <= 1 ? link : ''; } catch (e) { return ''; } }
